## 三、架构与核心算法代码（原文第2、3章，均✅代码块完整）

### 3.1 分层自适应架构（原文2.1）

```cpp
// 动态Tiling分层架构定义
class DynamicTilingArchitecture {
public:
    // 第一层：形状感知层
    class ShapeAwareLayer {
    public:
        virtual TensorShape analyze_shape_pattern(const DynamicShape& input) = 0;
        virtual bool validate_shape_compatibility(const TensorShape& shape) = 0;
    };
    // 第二层：资源规划层
    class ResourcePlanningLayer {
    public:
        virtual MemoryPlan plan_memory_allocation(const TensorShape& shape) = 0;
        virtual CoreAllocation plan_core_distribution(uint32_t total_workload) = 0;
    };
    // 第三层：执行优化层
    class ExecutionOptimizationLayer {
    public:
        virtual TilingStrategy select_optimal_strategy(const ExecutionContext& context) = 0;
        virtual void adapt_runtime_parameters(const PerformanceMetrics& metrics) = 0;
    };
    // 集成架构
    struct DynamicTilingResult {
        TilingParameters params;
        ResourceAllocation resources;
        OptimizationHints hints;
        float confidence_score;
    };
    DynamicTilingResult compute_adaptive_tiling(const DynamicShape& input_shape,
                                             const HardwareInfo& hw_info) {
        DynamicTilingResult result;
        // 1. 形状分析
        auto shape_analysis = shape_layer_.analyze_shape_pattern(input_shape);
        if (!shape_layer_.validate_shape_compatibility(shape_analysis)) {
            throw std::runtime_error("Shape validation failed");
        }
        // 2. 资源规划
        auto memory_plan = resource_layer_.plan_memory_allocation(shape_analysis);
        auto core_plan = resource_layer_.plan_core_distribution(shape_analysis.element_count());
        // 3. 策略选择
        ExecutionContext context{shape_analysis, memory_plan, core_plan, hw_info};
        result.params = optimization_layer_.select_optimal_strategy(context);
        // 4. 置信度评估
        result.confidence_score = evaluate_strategy_confidence(result.params, context);
        return result;
    }
private:
    ShapeAwareLayer shape_layer_;
    ResourcePlanningLayer resource_layer_;
    ExecutionOptimizationLayer optimization_layer_;
};
```

