- **自适应调度**：`Process()` 按 `enable_pipeline` 分支；`setup_global_memory()` 用 `GetBlockIdx()` 动态计算各核偏移；`setup_pipes_and_queues()` 动态选择双缓冲/单缓冲；`pipeline_*` 三段流水线含尾块（last_tile_size）处理

```cpp
// softmax_kernel.cpp - Kernel侧完整实现
#include "kernel_operator.h"
#include "softmax_tiling.h"

using namespace AscendC;

class DynamicSoftmaxKernel {
private:
    GlobalTensor input_gm_, output_gm_;
    DynamicSoftmaxTiling tiling_data_;
    Pipe pipe_;

    // 队列定义
    TQue<QuePosition::VECIN, 8> input_queue_;
    TQue<QuePosition::VECOUT, 8> output_queue_;
    TQue<QuePosition::VECCALC, 8> workspace_queue_;

public:
    __aicore__ void Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling_addr) {
        // 1. 解析Tiling数据
        GET_TILING_DATA(tiling_data_, tiling_addr);

        // 2. 设置全局内存地址
        setup_global_memory(input, output);

        // 3. 初始化管道和队列
        setup_pipes_and_queues();
    }

    __aicore__ void Process() {
        // 主处理流程
        if (tiling_data_.enable_pipeline()) {
            process_with_pipeline();
        } else {
            process_standard();
        }
    }

private:
    __aicore__ void setup_global_memory(GM_ADDR input, GM_ADDR output) {
        // 计算每个核心的数据偏移（考虑动态形状）
        uint32_t block_size = tiling_data_.total_elements() / tiling_data_.num_cores();
        uint32_t block_offset = block_size * GetBlockIdx();
        input_gm_.SetGlobalBuffer((__gm__ half*)input + block_offset, block_size);
        output_gm_.SetGlobalBuffer((__gm__ half*)output + block_offset, block_size);
    }

    __aicore__ void setup_pipes_and_queues() {
        // 基于Tiling参数初始化队列
        uint32_t buffer_size = tiling_data_.tile_size() * sizeof(half);
        if (tiling_data_.enable_pipeline()) {
            // 流水线模式：双缓冲
            pipe_.InitBuffer(input_queue_, 2, buffer_size);
            pipe_.InitBuffer(output_queue_, 2, buffer_size);
            pipe_.InitBuffer(workspace_queue_, 2, buffer_size / 2); // 归约 workspace
        } else {
            // 标准模式：单缓冲
            pipe_.InitBuffer(input_queue_, 1, buffer_size);
            pipe_.InitBuffer(output_queue_, 1, buffer_size);
            pipe_.InitBuffer(workspace_queue_, 1, buffer_size / 2);
        }
    }

    __aicore__ void process_with_pipeline() {
        // 流水线处理实现
        uint32_t loop_count = tiling_data_.blocks_per_core() * 2; // 双缓冲
        for (uint32_t i = 0; i < loop_count; ++i) {
            pipeline_copy_in(i);
            pipeline_compute(i);
            pipeline_copy_out(i);
        }
    }

    __aicore__ void pipeline_copy_in(uint32_t iteration) {
        uint32_t tile_index = iteration / 2;
        uint32_t buffer_index = iteration % 2;
        if (tile_index >= tiling_data_.num_tiles()) {
            return;
        }
        // 计算当前tile的全局偏移
        uint32_t global_offset = tile_index * tiling_data_.tile_size();
        uint32_t copy_size = (tile_index == tiling_data_.num_tiles() - 1) ? 
                           tiling_data_.last_tile_size() : tiling_data_.tile_size();
        // 异步数据搬入
        LocalTensor input_tensor = input_queue_.AllocTensor<half>();
        pipe_.Copy(input_tensor, input_gm_ + global_offset, copy_size * sizeof(half));
        input_queue_.EnQue<half>(input_tensor);
    }

    __aicore__ void pipeline_compute(uint32_t iteration) {
        if (iteration < 1) return; // 前几个迭代需要积累
        uint32_t compute_index = (iteration - 1) / 2;
        uint32_t buffer_index = (iteration - 1) % 2;
        // 从队列获取数据
        LocalTensor input_tensor = input_queue_.DeQue<half>();
        LocalTensor output_tensor = output_queue_.AllocTensor<half>();
        LocalTensor workspace_tensor = workspace_queue_.AllocTensor<float>();
        // 执行Softmax计算
        compute_softmax(input_tensor, output_tensor, workspace_tensor, 
                       tiling_data_.dim_size(), tiling_data_.inner_size());
        // 将结果放入输出队列
        output_queue_.EnQue<half>(output_tensor);
        workspace_queue_.EnQue<float>(workspace_tensor);
        input_queue_.FreeTensor(input_tensor);
    }

    __aicore__ void pipeline_copy_out(uint32_t iteration) {
        if (iteration < 2) return; // 前几个迭代需要积累
        uint32_t tile_index = (iteration - 2) / 2;
        uint32_t buffer_index = (iteration - 2) % 2;
        if (tile_index >= tiling_data_.num_tiles()) {
            return;
        }
        // 从队列获取结果
        LocalTensor output_tensor = output_queue_.DeQue<half>();
        LocalTensor workspace_tensor = workspace_queue_.DeQue<float>();
        // 计算输出偏移
        uint32_t global_offset = tile_index * tiling_data_.tile_size();
        uint32_t copy_size = (tile_index == tiling_data_.num_tiles() - 1) ? 
                           tiling_data_.last_tile_size() : tiling_data_.tile_size();
        // 异步数据搬出
        pipe_.Copy(output_gm_ + global_offset, output_tensor, copy_size * sizeof(half));
        output_queue_.FreeTensor(output_tensor);
        workspace_queue_.FreeTensor(workspace_tensor);
    }

    __aicore__ void compute_softmax(LocalTensor input, LocalTensor output,
                                  LocalTensor workspace, uint32_t dim_size,
                                  uint32_t inner_size) {
        // Softmax计算实现
        for (uint32_t i = 0; i < inner_size; ++i) {
            // 1. 寻找最大值（数值稳定）
            half max_val = find_max_value(input + i * dim_size, dim_size);
            // 2. 计算指数和
            half exp_sum = compute_exp_sum(input + i * dim_size, dim_size, max_val);
            // 3. 归一化计算
            compute_normalization(output + i * dim_size, input + i * dim_size,
                                dim_size, max_val, exp_sum);
        }
    }
};

// Kernel入口函数
extern "C" __global__ __aicore__ void dynamic_softmax_kernel(GM_ADDR input, 
                                                            GM_ADDR output,
                                                            GM_ADDR tiling) {
    DynamicSoftmaxKernel kernel;
    kernel.Init(input, output, tiling);
    kernel.Process();
}
```

