### 3.4 动态分块算法（原文3.2，✅代码块完整；核心策略：按可变性分三档——低可变性激进优化/中等平衡/高可变性保守）

```cpp
// 动态分块算法核心实现
class DynamicTilingAlgorithm {
public:
    struct TilingResult {
        uint32_t tile_size;
        uint32_t num_tiles;
        uint32_t last_tile_size;
        uint32_t num_cores;
        float load_imbalance_factor;
        size_t memory_requirement;
    };
    TilingResult compute_optimal_tiling(const DynamicShape& shape,
                                       const HardwareInfo& hw_info) {
        TilingResult result;
        // 1. 计算总工作量
        uint64_t total_elements = shape.element_count();
        // 2. 确定使用的核心数量（基于形状大小和硬件能力）
        result.num_cores = calculate_optimal_core_count(total_elements, hw_info);
        // 3. 计算基础分块参数
        auto base_tiling = calculate_base_tiling_parameters(total_elements, 
                                                            result.num_cores, hw_info);
        // 4. 基于形状特性调整策略
        result = adapt_tiling_to_shape_characteristics(base_tiling, shape, hw_info);
        // 5. 验证硬件约束满足情况
        validate_hardware_constraints(result, hw_info);
        return result;
    }
private:
    uint32_t calculate_optimal_core_count(uint64_t total_elements,
                                        const HardwareInfo& hw_info) {
        // 计算最优核心数：平衡并行度和单核效率
        uint32_t min_cores = 1;
        uint32_t max_cores = hw_info.available_cores;
        // 基于工作量估计的最佳核心数
        uint64_t elements_per_core = total_elements / max_cores;
        if (elements_per_core < hw_info.min_elements_per_core) {
            // 工作量太小，减少核心数避免资源浪费
            return std::max(min_cores, total_elements / hw_info.optimal_elements_per_core);
        } else if (elements_per_core > hw_info.max_elements_per_core) {
            // 工作量很大，使用所有可用核心
            return max_cores;
        } else {
            // 平衡点，基于经验公式计算
            return calculate_balanced_core_count(total_elements, hw_info);
        }
    }
    TilingResult adapt_tiling_to_shape_characteristics(const TilingResult& base,
                                                     const DynamicShape& shape,
                                                     const HardwareInfo& hw_info) {
        TilingResult adapted = base;
        // 基于形状的动态特性进行调整
        auto variability = analyze_shape_variability(shape);
        if (variability < LOW_VARIABILITY_THRESHOLD) {
            // 低可变性：使用激进优化
            adapted.tile_size = optimize_for_performance(adapted, hw_info);
        } else if (variability < HIGH_VARIABILITY_THRESHOLD) {
            // 中等可变性：平衡策略
            adapted.tile_size = optimize_for_balance(adapted, hw_info);
        } else {
            // 高可变性：保守策略保证稳定性
            adapted.tile_size = optimize_for_stability(adapted, hw_info);
        }
        // 重新计算分块数量
        adapted.num_tiles = (shape.element_count() + adapted.tile_size - 1) / adapted.tile_size;
        adapted.last_tile_size = shape.element_count() % adapted.tile_size;
        if (adapted.last_tile_size == 0) {
            adapted.last_tile_size = adapted.tile_size;
        }
        return adapted;
    }
};
